BEGIN;

-- The only genuine schema drift between production and staging:
-- staging.orders carries `currency`, production.orders does not.
-- Additive, with the same default staging uses, so existing rows backfill
-- to 'USD' and nothing is rewritten by the application.
ALTER TABLE production.orders
    ADD COLUMN currency text NOT NULL DEFAULT 'USD';

-- Row count must be unchanged; a column add never drops rows, so this is
-- a tripwire against having run something other than what is written here.
DO $$
DECLARE n bigint;
BEGIN
    SELECT count(*) INTO n FROM production.orders;
    IF n <> 4800 THEN
        RAISE EXCEPTION 'orders row count changed: expected 4800, got %', n;
    END IF;
END
$$;

COMMIT;
SQL
